<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bandingkan Produk — Aphrodite</title><script src="https://cdn.tailwindcss.com"></script><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:wght@500;600;700&display=swap" rel="stylesheet"><style>body{font-family:'DM Sans',sans-serif}.serif{font-family:'Playfair Display',serif}</style></head>
<body class="min-h-screen bg-[#FFFEFA] text-[#345452]"><nav class="bg-[#FDEEF1] px-5 py-4"><div class="mx-auto flex max-w-6xl justify-between"><a href="/" class="text-xl font-extrabold text-[#E6748E]">Aphrodite</a><a href="/kuis" class="text-sm font-bold">Kuis analisis →</a></div></nav>
<main class="mx-auto max-w-6xl px-4 py-10 sm:px-6"><p class="text-xs font-extrabold uppercase tracking-[.25em] text-[#6BB1AD]">Pilih hingga tiga produk</p><h1 class="serif mt-2 text-4xl font-bold text-[#E6748E]">Bandingkan skincare</h1><p class="mt-2 text-sm text-[#657674]">Informasi produk diambil langsung dari ontologi melalui Fuseki.</p>
<section class="mt-8 rounded-3xl border border-[#E6748E]/10 bg-white p-5 shadow-sm"><label for="search" class="mb-2 block text-sm font-bold">Cari produk</label><input id="search" type="search" placeholder="Ketik nama produk…" class="w-full rounded-xl border border-[#6BB1AD]/30 px-4 py-3 outline-none focus:border-[#6BB1AD]"><p id="count" class="mt-3 text-xs font-bold text-[#657674]">0 dari 3 produk dipilih</p><div id="catalog" class="mt-4 grid gap-2 sm:grid-cols-2"></div><div id="message" class="mt-4 text-sm text-[#E6748E]" role="status"></div></section>
<section class="mt-8"><h2 class="serif mb-4 text-2xl font-bold">Tabel perbandingan</h2><div id="comparison" class="overflow-x-auto rounded-3xl border border-[#E6748E]/10 bg-white p-4"><p class="py-8 text-center text-sm text-[#657674]">Pilih produk untuk mulai membandingkan.</p></div></section>
<p class="mt-5 text-xs text-[#657674]">Ontologi saat ini tidak menyediakan foto produk, klaim, atau relasi konflik bahan aktif. Kolom tersebut ditandai sebagai data yang belum tersedia.</p></main>
<script>
(()=>{const catalog=document.querySelector('#catalog'),search=document.querySelector('#search'),message=document.querySelector('#message'),comparison=document.querySelector('#comparison'),count=document.querySelector('#count');let products=[],selected=[];try{selected=JSON.parse(localStorage.getItem('aphrodite-compare')||'[]').slice(0,3)}catch{}const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderCatalog(){const q=search.value.toLowerCase();catalog.innerHTML=products.filter(p=>p.name.toLowerCase().includes(q)).slice(0,80).map(p=>`<label class="flex cursor-pointer items-center gap-3 rounded-xl border border-[#E6748E]/10 p-3 text-sm hover:border-[#6BB1AD]"><input type="checkbox" value="${esc(p.id)}" ${selected.includes(p.id)?'checked':''} class="accent-[#6BB1AD]"><span>${esc(p.name)}</span><span class="ml-auto text-xs text-[#657674]">${esc(p.id)}</span></label>`).join('')||'<p class="text-sm text-[#657674]">Produk tidak ditemukan.</p>';catalog.querySelectorAll('input').forEach(el=>el.onchange=()=>{message.textContent='';if(el.checked){if(selected.length>=3){el.checked=false;message.textContent='Maksimal tiga produk dapat dibandingkan.';return}selected.push(el.value)}else selected=selected.filter(id=>id!==el.value);localStorage.setItem('aphrodite-compare',JSON.stringify(selected));update()});count.textContent=`${selected.length} dari 3 produk dipilih`}
function fmt(v){return v==null?'Tidak tersedia':typeof v==='number'?'Rp'+new Intl.NumberFormat('id-ID').format(v):esc(v)}
function draw(items){if(!items.length){comparison.innerHTML='<p class="py-8 text-center text-sm text-[#657674]">Pilih produk untuk mulai membandingkan.</p>';return}const fields=[['Foto','image'],['Nama','name'],['Brand','brand'],['Seri','series'],['Kategori','category'],['Harga','price'],['Jenis kulit','skin_types'],['Kelompok umur','age_groups'],['Keluhan','concerns'],['Bahan aktif','ingredients'],['Klaim','claims']];comparison.innerHTML=`<table class="min-w-[650px] w-full border-collapse text-left text-sm"><thead><tr><th class="sticky left-0 bg-[#FDEEF1] p-3">Informasi</th>${items.map(p=>`<th class="min-w-48 bg-[#FDEEF1] p-3 align-top"><div class="font-bold">${esc(p.name)}</div><button data-remove="${esc(p.id)}" class="mt-2 text-xs font-bold text-[#E6748E] underline">Hapus</button></th>`).join('')}</tr></thead><tbody>${fields.map(([label,key])=>{let vals=items.map(p=>{if(key==='image')return 'Tidak tersedia di ontologi';let v=p[key];return Array.isArray(v)?(v.length?v.map(esc).join(', '):'Tidak tersedia'):fmt(v)});let different=new Set(vals).size>1;return `<tr class="border-t border-[#E6748E]/10"><th class="sticky left-0 bg-white p-3 font-bold">${label}</th>${vals.map(v=>`<td class="p-3 ${different?'bg-[#B8E8EE]/30 font-semibold':''}">${v}</td>`).join('')}</tr>`}).join('')}</tbody></table><p class="mt-4 rounded-xl bg-[#FDEEF1] p-3 text-xs text-[#657674]">${items.some(p=>p.ingredients.length>0)?'Pemeriksaan konflik bahan aktif belum dapat dipastikan karena ontologi belum mendefinisikan aturan kompatibilitas.':''}</p>`;comparison.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{selected=selected.filter(id=>id!==b.dataset.remove);localStorage.setItem('aphrodite-compare',JSON.stringify(selected));update()})}
let timer;async function update(){renderCatalog();if(!selected.length){draw([]);return}comparison.innerHTML='<p class="py-8 text-center text-sm">Memuat data dari Fuseki…</p>';try{const params=new URLSearchParams();selected.forEach(id=>params.append('ids[]',id));const r=await fetch('/api/products/compare?'+params);const data=await r.json();if(!r.ok)throw new Error(data.message||'Tidak dapat memuat data produk.');draw(data.products)}catch(e){comparison.innerHTML=`<p class="py-8 text-center text-sm text-red-700">${esc(e.message)}</p>`}}
search.oninput=()=>{clearTimeout(timer);timer=setTimeout(renderCatalog,120)};fetch('/api/products').then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.message||'Tidak dapat memuat katalog.');products=d.products;selected=selected.filter(id=>products.some(p=>p.id===id));localStorage.setItem('aphrodite-compare',JSON.stringify(selected));await update()}).catch(e=>{message.textContent=e.message;catalog.innerHTML=''});
})();
</script></body></html>
